// Embeds the sandbox-side shell scripts in src/cloud/bootstrap/assets/*.sh into
// src/cloud/bootstrap/generated/assets.ts, so `runpane cloud` can upload them from the npm
// package (and the copy bundled in the Pane app) without shipping loose files.
// `--check` fails when the generated file is stale.
const fs = require('fs');
const path = require('path');

const bootstrapDir = path.resolve(__dirname, '..', 'src', 'cloud', 'bootstrap');
const assetsDir = path.join(bootstrapDir, 'assets');
const outFile = path.join(bootstrapDir, 'generated', 'assets.ts');

const names = fs.readdirSync(assetsDir).filter((name) => name.endsWith('.sh')).sort();
const entries = names.map((name) => `  ${JSON.stringify(name)}: ${JSON.stringify(fs.readFileSync(path.join(assetsDir, name), 'utf8'))},`);
const output = [
  '// Generated by packages/runpane/scripts/generate-cloud-assets.js from src/cloud/bootstrap/assets. Do not edit.',
  'export const cloudBootstrapAssets = {',
  ...entries,
  '} as const;',
  '',
  'export type CloudBootstrapAssetName = keyof typeof cloudBootstrapAssets;',
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : '';
  if (current !== output) {
    console.error(`${path.relative(process.cwd(), outFile)} is stale; run node packages/runpane/scripts/generate-cloud-assets.js`);
    process.exit(1);
  }
} else {
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, output);
}
